const rows=$input.all().map(i=>i.json).filter(r=>String(r.IDENTIFICACAO||'').trim());
const t=v=>String(v??'').trim().replace(/^'/,'');
const yes=v=>/^sim$/i.test(t(v));
const result=rows.map(r=>({
 id:t(r.IDENTIFICACAO),nf:t(r.NOTA_FISCAL),serie:t(r.SERIE_NF),chave:t(r.CHAVE_NFE),carro:t(r.CARRO),
 marca:t(r.MARCA),ref:t(r.REFERENCIA),material:t(r.DESCRICAO_MATERIAL),canal:t(r.CANAL),
 pecas:r.QUANTIDADE??'',valor:r.VALOR??'',agend:t(r.DATA_AGENDAMENTO),conf:t(r.FIM_CONFERENCIA_SUL),
 embarque:t(r.DATA_EMBARQUE),previsao:t(r.PREVISAO_CHEGADA),rom:t(r.ROMANEIO),transp:t(r.TRANSPORTADORA),
 recebido:yes(r.RECEBIMENTO_RIO),obs:t(r.OBSERVACAO_RECEBIMENTO),dataRio:t(r.DATA_RECEBIMENTO_RIO),
 entrada:t(r.DATA_ENTRADA_FISCAL),mensagem:t(r.MENSAGEM),statusIntegracao:t(r.STATUS_INTEGRACAO),
 inicioConferencia:t(r.INICIO_CONFERENCIA_SUL),placa:t(r.PLACA),motorista:t(r.MOTORISTA),atualizado:t(r.ULTIMA_ATUALIZACAO)
}));
return [{json:{ok:true,total:result.length,rows:result}}];

let b=$input.first().json.body??{};
if(typeof b==='string'){try{b=JSON.parse(b)}catch(e){b={}}}
const id=String(b.id??'').replace(/^'/,'').trim();
const action=String(b.acao??'').trim();
const novo=String(b.valor??'').trim();
let erro='';
if(!/^\d{9}-\d{1,3}$/.test(id))erro='Identificação inválida.';
else if(!['carro','observacao','recebimento'].includes(action))erro='Ação não permitida.';
else if(action==='carro'&&(!novo||novo.length>60))erro='Informe um carro válido (até 60 caracteres).';
else if(action==='observacao'&&novo.length>500)erro='Observação acima de 500 caracteres.';
else if(action==='recebimento'&&b.confirmar!==true)erro='Confirmação explícita necessária.';
return [{json:{ok:!erro,erro,id,acao:action,valor:novo}}];

const req=$('API - Validar alteração').first().json;
const t=v=>String(v??'').trim().replace(/^'/,'');
const rows=$input.all().map(i=>i.json).filter(r=>t(r.IDENTIFICACAO)===req.id);
const fail=erro=>[{json:{ok:false,erro}}];
if(rows.length!==1)return fail(rows.length?'Identificação duplicada na planilha.':'NF não encontrada na planilha.');
const row=rows[0];const now=$now.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd HH:mm:ss');
const upd={IDENTIFICACAO:req.id,ULTIMA_ATUALIZACAO:now};
const safe=v=>"'"+v.replace(/^'/,'');
if(req.acao==='carro'){if(t(row.CARRO)===req.valor)return [{json:{ok:true,semMudanca:true}}];upd.CARRO=safe(req.valor)}
if(req.acao==='observacao'){if(t(row.OBSERVACAO_RECEBIMENTO)===req.valor)return [{json:{ok:true,semMudanca:true}}];upd.OBSERVACAO_RECEBIMENTO=req.valor?safe(req.valor):''}
if(req.acao==='recebimento'){
 if(/^sim$/i.test(t(row.RECEBIMENTO_RIO)))return fail('Esta NF já foi recebida. Não é permitido desfazer o recebimento.');
 upd.RECEBIMENTO_RIO='Sim';upd.DATA_RECEBIMENTO_RIO=now;
}
return [{json:{ok:true,semMudanca:false,...upd}}];

let b=$input.first().json.body??{};if(typeof b==='string'){try{b=JSON.parse(b)}catch(e){b={}}}
const car=String(b.carro??'').trim();const serie=String(b.serie??'').trim();const nfs=Array.isArray(b.nfs)?b.nfs.map(v=>String(v).trim()):[];
let erro='';
if(!car||car.length>60)erro='Informe o carro (até 60 caracteres).';
else if(!/^\d{1,3}$/.test(serie))erro='Série inválida.';
else if(!nfs.length||nfs.length>100)erro='Informe de 1 a 100 NFs.';
else if(nfs.some(n=>!/^\d{1,9}$/.test(n)))erro='As NFs devem conter até 9 dígitos numéricos.';
const ids=nfs.map(n=>n.padStart(9,'0')+'-'+Number(serie));
if(!erro&&new Set(ids).size!==ids.length)erro='Existem NFs repetidas no lote.';
return [{json:{ok:!erro,erro,carro:car,serie:String(Number(serie)),ids,nfs:ids.join(','),chaves:''}}];

const req=$('API - Validar lote').first().json;
const sql=$('API - Consultar faturamento').all().map(x=>x.json).filter(x=>x.CHAVE_NFE);
const t=v=>String(v??'').trim().replace(/^'/,'');const num=v=>String(v??'').replace(/\D/g,'');
const id=(nf,serie)=>num(nf).padStart(9,'0')+'-'+String(Number(num(serie)));
const byId=new Map();for(const d of sql){const k=id(d.NF_SAIDA,d.SERIE_NF);if(!byId.has(k))byId.set(k,[]);byId.get(k).push(d)}
const existing=$input.all().map(x=>x.json).filter(x=>t(x.IDENTIFICACAO));
const knownIds=new Set(existing.map(r=>t(r.IDENTIFICACAO)));
const knownKeys=new Set(existing.map(r=>num(r.CHAVE_NFE)).filter(Boolean));
const failures=[];const newRows=[];const now=$now.setZone('America/Sao_Paulo').toFormat('yyyy-MM-dd HH:mm:ss');
const T=v=>"'"+t(v);
for(const k of req.ids){
 const list=byId.get(k)||[];
 if(knownIds.has(k)){failures.push(`${k}: já cadastrada`);continue}
 if(!list.length){failures.push(`${k}: não localizada no faturamento`);continue}
 if(list.length>1){failures.push(`${k}: localizada em mais de uma filial, use a chave`);continue}
 const d=list[0];if(knownKeys.has(num(d.CHAVE_NFE))){failures.push(`${k}: chave já cadastrada`);continue}
 newRows.push({IDENTIFICACAO:T(k),NOTA_FISCAL:T(num(d.NF_SAIDA).padStart(9,'0')),CARRO:T(req.carro),
 MARCA:t(d.MARCA),REFERENCIA:T(d.REFERENCIA),DESCRICAO_MATERIAL:T(d.DESCRICAO_MATERIAL),CANAL:t(d.CANAL),
 QUANTIDADE:Number(d.QUANTIDADE??0),VALOR:Number(d.VALOR??0),STATUS_INTEGRACAO:'INTEGRADO',
 DATA_AGENDAMENTO:t(d.DATA_AGENDAMENTO),INICIO_CONFERENCIA_SUL:t(d.INICIO_CONFERENCIA_SUL),FIM_CONFERENCIA_SUL:t(d.FIM_CONFERENCIA_SUL),
 DATA_EMBARQUE:t(d.DATA_EMBARQUE),PREVISAO_CHEGADA:t(d.PREVISAO_CHEGADA),RECEBIMENTO_RIO:'Não',
 DATA_ENTRADA_FISCAL:t(d.DATA_ENTRADA_FISCAL),ROMANEIO:t(d.ROMANEIO)?T(d.ROMANEIO):'',PLACA:t(d.PLACA)?T(d.PLACA):'',
 MOTORISTA:t(d.MOTORISTA)?T(d.MOTORISTA):'',SERIE_NF:T(d.SERIE_NF),CHAVE_NFE:T(d.CHAVE_NFE),
 TRANSPORTADORA:t(d.TRANSPORTADORA)?T(d.TRANSPORTADORA):'',MENSAGEM:'',ULTIMA_ATUALIZACAO:now});
}
// Não gravar lote parcialmente: evita registros inesperados no fechamento operacional.
if(failures.length)return [{json:{ok:false,erro:'Lote recusado. Nenhuma NF foi cadastrada.',detalhes:failures}}];
return newRows.map(r=>({json:{ok:true,...r}}));
